const input = $input.first().json;
const { whatsapp, horario_id, tipo_pago, monto, comprobante_url, estado_pago } = input;

if (!whatsapp || !tipo_pago || !monto) {
  throw new Error('whatsapp, tipo_pago y monto son requeridos');
}

if (!['VERIFICADO', 'PENDIENTE_VERIFICACION'].includes(estado_pago)) {
  throw new Error('estado_pago debe ser VERIFICADO o PENDIENTE_VERIFICACION');
}

const queries = {
  alumnoId: `SELECT id FROM alumnos WHERE whatsapp = '${whatsapp}'`,
  pago: `INSERT INTO pagos (alumno_id, horario_id, tipo, canal, monto, estado, comprobante_url, created_at) VALUES ((SELECT id FROM alumnos WHERE whatsapp = '${whatsapp}'), ${horario_id || 'NULL'}, '${tipo_pago}', 'AGENTE', ${monto}, '${estado_pago}', '${comprobante_url || ''}', NOW())`,
  update: `UPDATE alumnos SET estado_pago = '${estado_pago}', fecha_pago_ultimo = NOW(), ultimo_contacto = NOW(), updated_at = NOW() WHERE whatsapp = '${whatsapp}'`
};

return [{ json: { input, queries } }];

const input = $('Validar entrada').first().json.input;
const estado = input.estado_pago;

const response = {
  success: true,
  pago_registrado: {
    monto: input.monto,
    tipo: input.tipo_pago,
    estado: estado,
    comprobante_url: input.comprobante_url
  },
  alumno_estado: estado === 'VERIFICADO' ? 'ACTIVO' : 'PAUSADO',
  mensaje: estado === 'VERIFICADO' ? '✓ Pago verificado y registrado' : '⏳ Pago registrado, pendiente revisión de Fla'
};

return [{ json: response }];
